/* @lc app=leetcode id=2402 lang=kotlin */
class Solution { fun mostBooked(n: Int, meetings: Array<IntArray>): Int = LongArray(n).let { t -> IntArray(n).let { c -> java.util.PriorityQueue<Int>((0 until n).toList()).let { f -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy({ it.first }, { it.second })).let { b -> meetings.sortedBy { it[0] }.forEach { m -> generateSequence { b.peek()?.takeIf { it.first <= m[0].toLong() } }.forEach { f.add(b.poll().second) }.run { (if (f.isEmpty()) b.poll().let { (it.first + m[1] - m[0]) to it.second } else (m[1].toLong() to f.poll()!!)).let { (end, r) -> b.add(end to r).run { c[r]++ } } } }.run { c.indices.maxByOrNull { c[it] } ?: 0 } } } } }